package com.acme.restaurant.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * Calculates an order total from lines, promotions, service charge and tax.
 */
public class OrderTotalCalculator {

    private final PromotionEngine promotions;
    private final ServiceChargeRule serviceCharge;
    private final TaxTable tax;

    public OrderTotalCalculator(PromotionEngine promotions, ServiceChargeRule serviceCharge, TaxTable tax) {
        this.promotions = promotions;
        this.serviceCharge = serviceCharge;
        this.tax = tax;
    }

    public OrderTotal calculate(List<OrderLine> lines, String channel) {
        BigDecimal subtotal = lines.stream()
            .map(l -> l.getUnitPrice().multiply(BigDecimal.valueOf(l.getQuantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal discount = promotions.discountFor(lines, subtotal);
        BigDecimal service = serviceCharge.forChannel(channel, subtotal.subtract(discount));
        BigDecimal taxAmt = tax.forSubtotal(subtotal.subtract(discount));
        BigDecimal total = subtotal.subtract(discount).add(service).add(taxAmt);
        return new OrderTotal(subtotal, discount, service, taxAmt, total.setScale(2, RoundingMode.HALF_UP));
    }
}

