package com.acme.restaurant.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Order placement endpoint: persist, push to kitchen, return order number.
 */
@RestController
public class PlaceOrderController {

    private final SoldOutItemGuard soldOut;
    private final OrderRepository orders;
    private final KitchenDisplayGateway kitchen;

    public PlaceOrderController(SoldOutItemGuard soldOut, OrderRepository orders, KitchenDisplayGateway kitchen) {
        this.soldOut = soldOut;
        this.orders = orders;
        this.kitchen = kitchen;
    }

    @PostMapping("/orders")
    public OrderConfirmation place(@RequestBody PlaceOrderRequest req) {
        for (OrderLineRequest l : req.getLines()) {
            soldOut.assertOrderable(l.getMenuItemId());
        }
        Order o = orders.save(Order.from(req));
        kitchen.push(o.toKitchenTicket());
        return new OrderConfirmation(o.getOrderNumber(), o.getPlacedAt());
    }
}

