import java.util.Comparator;
import java.util.List;

/**
 * Builds the kitchen display queue and applies item status changes.
 */
public class KitchenDisplayService {

    private final OrderRepository orders;

    public KitchenDisplayService(OrderRepository orders) {
        this.orders = orders;
    }

    public List<KitchenTicket> queue() {
        return orders.findActive().stream()
            .sorted(Comparator.comparing(Order::getPlacedAt))
            .map(Order::toKitchenTicket)
            .toList();
    }

    public void updateItemStatus(String orderId, String lineId, KitchenItemStatus status) {
        Order o = orders.require(orderId);
        o.setLineStatus(lineId, status);
        orders.save(o);
    }
}

