package com.acme.restaurant.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Appends an audit entry on each order status change.
 */
public class OrderStatusAuditor {

    private final EntityManager em;

    public OrderStatusAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String orderId, String oldStatus, String newStatus, String staffId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            OrderStatusEntry e = new OrderStatusEntry();
            e.setOrderId(orderId);
            e.setOldStatus(oldStatus);
            e.setNewStatus(newStatus);
            e.setStaffId(staffId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

