#include <stdio.h>
#include "restaurant_db.h"

int write_category_report(const char *business_date, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "category,items_sold,revenue\n");

    db_cursor_t *cur = NULL;
    if (db_open_category_sales_cursor(&cur, business_date) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    category_sales_row_t row;
    while (db_category_cursor_next(cur, &row) == DB_OK) {
        if (row.cancelled_count > 0 || row.refunded_count > 0) continue;
        fprintf(out, "%s,%d,%.2f\n", row.category, row.items_sold, row.revenue);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

